def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find complete colored stripes in each of the three possible orientations.
    horizontal = {r: next(iter(set(row))) for r, row in enumerate(grid)
                  if row and row[0] != 0 and all(v == row[0] for v in row)}
    if horizontal:
        period = len(horizontal)
        by_residue = {r % period: color for r, color in horizontal.items()}
        # These examples encode one color for every residue in the period.
        return [[by_residue[r % period] for _ in range(w)] for r in range(h)]

    for diagonal_sum in (False, True):
        lines = {}
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if not color:
                    continue
                key = (r + c) if diagonal_sum else (c - r)
                lines.setdefault(key, []).append(color)
        # A stripe is a constant diagonal. Use only complete, uniformly colored stripes.
        stripe_colors = {}
        for key, cells in lines.items():
            coords = [(r, c) for r in range(h) for c in range(w)
                      if ((r + c) if diagonal_sum else (c - r)) == key]
            if len(cells) == len(coords) and len(set(cells)) == 1:
                stripe_colors[key] = cells[0]
        if stripe_colors:
            period = len(stripe_colors)
            by_residue = {key % period: color for key, color in stripe_colors.items()}
            return [[by_residue[((r + c) if diagonal_sum else (c - r)) % period]
                     for c in range(w)] for r in range(h)]
    return [row[:] for row in grid]
